@font-face {
  font-family: 'Inter';
  src: url('/fonts/inter/400.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* unicode-range lets the browser fetch only what it needs */
@font-face {
  font-family: 'Inter';
  src: url('/fonts/inter-400.woff2') format('woff2');
  font-weight: 400;
  unicode-range: U+0000-00FF, U+0131, U+0152-0153;
}

/* functional */
body { font-family: 'Inter', system-ui, sans-serif; }

/* long-form or brand voice */
.prose { font-family: 'Source Serif 4', Georgia, serif; }

:root {
  --t-xs:  0.75rem;  line-height: 1.4;  letter-spacing: 0;
  --t-sm:  0.875rem; line-height: 1.5;  letter-spacing: 0;
  --t-lg:  1.25rem;  line-height: 1.3;  letter-spacing: -0.005em;
  --t-xl:  2rem;     line-height: 1.15; letter-spacing: -0.015em;
  --t-display: 3.5rem; line-height: 1.05; letter-spacing: -0.025em;
}
